import{_ as t,o as i,c as a,a2 as o}from"./chunks/framework.BeV4qZ1B.js";const u=JSON.parse('{"title":"Limitations — BabelFHIR-TS","description":"Known limitations of BabelFHIR-TS including unsupported FHIR profiling patterns, random() edge cases, FHIRPath coverage gaps, and how to report issues.","frontmatter":{"title":"Limitations — BabelFHIR-TS","description":"Known limitations of BabelFHIR-TS including unsupported FHIR profiling patterns, random() edge cases, FHIRPath coverage gaps, and how to report issues.","head":[["link",{"rel":"canonical","href":"https://babelfhir-ts.github.io/parity-report/docs/limitations.html"}],["meta",{"name":"description","content":"Known limitations of BabelFHIR-TS including unsupported FHIR profiling patterns, random() edge cases, FHIRPath coverage gaps, and how to report issues."}],["meta",{"property":"og:description","content":"Known limitations of BabelFHIR-TS including unsupported FHIR profiling patterns, random() edge cases, FHIRPath coverage gaps, and how to report issues."}],["meta",{"name":"twitter:description","content":"Known limitations of BabelFHIR-TS including unsupported FHIR profiling patterns, random() edge cases, FHIRPath coverage gaps, and how to report issues."}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://babelfhir-ts.github.io/parity-report/docs/limitations.html#article\\",\\"headline\\":\\"Limitations — BabelFHIR-TS\\",\\"description\\":\\"Known limitations of BabelFHIR-TS including unsupported FHIR profiling patterns, random() edge cases, FHIRPath coverage gaps, and how to report issues.\\",\\"url\\":\\"https://babelfhir-ts.github.io/parity-report/docs/limitations.html\\",\\"inLanguage\\":\\"en-US\\",\\"isPartOf\\":{\\"@id\\":\\"https://babelfhir-ts.github.io/parity-report/docs/#website\\"},\\"about\\":{\\"@id\\":\\"https://github.com/babelfhir-ts/BabelFHIR-TS#app\\"},\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"Maximilian Nussbaumer\\"},\\"publisher\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"Maximilian Nussbaumer\\"},\\"license\\":\\"https://opensource.org/licenses/ISC\\",\\"proficiencyLevel\\":\\"Expert\\",\\"dateModified\\":\\"2026-09-30T20:41:39.000Z\\"}"]]},"headers":[],"relativePath":"limitations.md","filePath":"limitations.md","lastUpdated":1790800899000}'),n={name:"limitations.md"};function r(s,e,l,d,p,c){return i(),a("div",null,[...e[0]||(e[0]=[o('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /parity-report/docs/limitations.md for this page in Markdown format</div><h1 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h1><p>BabelFHIR-TS is a code generation tool that parses FHIR StructureDefinitions and produces TypeScript interfaces and validators. While it handles many common FHIR profiling patterns, there are important limitations to be aware of.</p><h2 id="fhir-version-support" tabindex="-1">FHIR Version Support <a class="header-anchor" href="#fhir-version-support" aria-label="Permalink to &quot;FHIR Version Support&quot;">​</a></h2><ul><li><strong>R4, R4B, and R5</strong> are supported. The FHIR version is auto-detected from the package or can be set with <code>--fhir-version</code>.</li><li><strong>Dependencies</strong> — generated code depends on <code>@types/fhir</code> (R4/R4B/R5 definitions) and <code>fhirpath</code> (peer dependency for validators).</li><li><strong><code>@types/fhir</code> gaps</strong> — <code>@types/fhir</code> does not export <code>SimpleQuantity</code> or <code>MoneyQuantity</code> (FHIR constraint profiles on <code>Quantity</code>). BabelFHIR-TS ships its own type aliases to fill this gap. See <a href="https://github.com/DefinitelyTyped/DefinitelyTyped/issues/74830" target="_blank" rel="noreferrer">DefinitelyTyped#74830</a>.</li></ul><h2 id="profile-mapping-accuracy" tabindex="-1">Profile Mapping Accuracy <a class="header-anchor" href="#profile-mapping-accuracy" aria-label="Permalink to &quot;Profile Mapping Accuracy&quot;">​</a></h2><ul><li><strong>Not guaranteed for all IGs</strong> — the generator uses heuristics to interpret StructureDefinition constraints, slicing rules, and extensions. Complex or unusual profiling patterns may not map correctly to TypeScript.</li><li><strong>Test before production</strong> — always validate the generated code against your specific Implementation Guide&#39;s examples and test cases. We recommend running the official FHIR validator alongside BabelFHIR-TS in your QA pipeline.</li><li><strong>Edge cases</strong> — rare profiling constructs (deeply nested slicing, conditional constraints, complex discriminators) may generate suboptimal or incomplete types.</li></ul><h2 id="typescript-limitations" tabindex="-1">TypeScript Limitations <a class="header-anchor" href="#typescript-limitations" aria-label="Permalink to &quot;TypeScript Limitations&quot;">​</a></h2><ul><li><strong>Runtime type checking is limited</strong> — TypeScript types are erased at compile time. The generated interfaces provide compile-time safety but cannot enforce constraints at runtime without the validator functions.</li><li><strong>Extension slicing</strong> — while the generator creates typed extension interfaces, TypeScript cannot enforce that extension arrays contain exactly the required slices at compile time (this is validated at runtime).</li><li><strong>Choice types</strong> — FHIR&#39;s <code>[x]</code> choice types (e.g., <code>value[x]</code>) are represented as union types in TypeScript, which may require runtime type narrowing.</li></ul><h2 id="random-method" tabindex="-1"><code>random()</code> Method <a class="header-anchor" href="#random-method" aria-label="Permalink to &quot;`random()` Method&quot;">​</a></h2><p>The generated <code>.random()</code> methods create test data that satisfies TypeScript types and basic cardinality, but <strong>do not guarantee</strong> fully valid FHIR resources. Random data may violate:</p><ul><li>Complex FHIRPath invariants</li><li>ValueSet bindings (codes are randomly chosen from required bindings but not guaranteed to be semantically correct)</li><li>Profile-specific business rules</li><li>Reference integrity constraints</li></ul><p>Use <code>random()</code> for development, testing, and prototyping, but always validate production data on the FHIR server side.</p><h2 id="validate-method" tabindex="-1"><code>validate()</code> Method <a class="header-anchor" href="#validate-method" aria-label="Permalink to &quot;`validate()` Method&quot;">​</a></h2><p>The generated validation methods execute FHIRPath expressions and check constraints from StructureDefinitions. They are tested against the HL7 Java Validator and the Firely SDK Validator for the Implementation Guides listed in the <a href="./validation.html">Validation</a> page.</p><p>Edge cases, complex slicing patterns, or profiles not in the CI pipeline may produce different results. For production conformance testing, use the official <a href="https://confluence.hl7.org/display/FHIR/Using+the+FHIR+Validator" target="_blank" rel="noreferrer">HL7 FHIR Validator</a> as the source of truth.</p><h2 id="reporting-issues" tabindex="-1">Reporting Issues <a class="header-anchor" href="#reporting-issues" aria-label="Permalink to &quot;Reporting Issues&quot;">​</a></h2><p>If you encounter an Implementation Guide that doesn&#39;t generate correctly, please <a href="https://github.com/babelfhir-ts/BabelFHIR-TS/issues" target="_blank" rel="noreferrer">open an issue</a> with:</p><ul><li>The package name and version</li><li>The specific StructureDefinition URL</li><li>Expected vs. actual generated output</li><li>Any validation errors or type mismatches</li></ul>',19)])])}const m=t(n,[["render",r]]);export{u as __pageData,m as default};
